/// <summary>
/// Extension of modifiedField method
/// </summary>
/// <param name = "_fieldId">FieldId</param>
/// <param name = "_userInput">boolean</param>
public void modifiedField(FieldId _fieldId, boolean _userInput)
{
    next modifiedField(_fieldId, _userInput);

    switch(_fieldId)
    {
        case fieldNum(SalesQuotationLine, KCS_PriceDate):
        case fieldNum(SalesQuotationLine, PriceUnit) :
            this.avaUpdateHK2();
            break;
    }
}

/// <summary>
/// updates relevant SalesLine fields - intended to be called after a CustAccountNum change in the header
/// </summary>
public void avaUpdateFieldsCustAccountChanged()
{
    this.AVApriceCalculation();
    this.avaUpdateHK2();
    this.initFromCustExternalItemDescription();
}

/// <summary>
/// method to update HK values and related fields
/// </summary>
public void avaUpdateHK2()
{
    this.KCS_HK2                = this.AVAgetHK2SalesUnit(); 
    this.AVAHKQuotCurrency      = this.AVAcalcHKQuotCurrency();
    this.KCS_LimitPrice         = this.AVAcalcLimitPrice();
    this.KCS_LimitPricePuffer   = this.AVAcalcLimitPricePuffer();
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_calcSalesPrice">_calcSalesPrice</param>
/// <param name = "_calcPriceDiscount">_calcPriceDiscount</param>
/// <param name = "_netPG1Price">_netPG1Price</param>
/// <param name = "_netPG2Price">_netPG2Price</param>
/// <param name = "_calcMasterPrice">_calcMasterPrice</param>
public void AVApriceCalculation(boolean      _calcSalesPrice = true,
                                boolean      _calcPriceDiscount = true,
                                boolean      _netPG1Price = true,
                                boolean      _netPG2Price = true,
                                boolean      _calcMasterPrice = true)
{
    SalesQuotationTable     salesQuotationTable = this.salesQuotationTable();
    SalesPrice              masterSalesPrice;
    PriceDiscTable          priceDiscTable;
    SalesQuotationLine      existedQuotLineItem;
    #define.M('M')

    if (_calcSalesPrice)
    {
        priceDiscTable =  AVAPriceDiscGroupSearch::findPriceDisc(PriceType::PriceSales,
                                                                  salesQuotationTable.PriceGroupId,
                                                                  salesQuotationTable.KCS_ChainLineDiscCode,
                                                                  this.itemId,
                                                                  this.KCS_PriceDate != dateNull() ? this.KCS_PriceDate : DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),
                                                                  salesQuotationTable.CurrencyCode);

        this.KCS_LPSalesPrice = salesQuotationTable.CurrencyCode == priceDiscTable.Currency ? priceDiscTable.Amount : 
                                                                    salesQuotationTable.AVAExchangeRate != 0 ? (priceDiscTable.Amount *salesQuotationTable.AVAExchangeRate  ) /  100 :
                                                                    CurrencyExchangeHelper::amount(priceDiscTable.Amount,priceDiscTable.Currency);

    }
    if (_calcPriceDiscount)
    {
        this.AVALPPriceDiscount = AVAPriceDiscGroupSearch::findPriceDisc(PriceType::LineDiscSales,
                                                                  salesQuotationTable.LineDisc,
                                                                  salesQuotationTable.KCS_ChainLineDiscCode, //ToDo : Positionsrabattgruppe Kette aus dem Auftragskopf
                                                                  this.itemId,
                                                                  this.KCS_PriceDate != dateNull() ? this.KCS_PriceDate : DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),
                                                                  salesQuotationTable.CurrencyCode).Percent1;
    }

    this.AVALPDiscountedPrice =  this.KCS_LPSalesPrice * (1 -   this.AVALPPriceDiscount/100);
    if(_netPG1Price)
    {
        priceDiscTable =   AVAPriceDiscGroupSearch::findPriceDisc(PriceType::PriceSales,
                                                                  salesQuotationTable.AVANetPG1,
                                                                  salesQuotationTable.KCS_ChainLineDiscCode,
                                                                  this.itemId,
                                                                  this.KCS_PriceDate != dateNull() ? this.KCS_PriceDate : DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),
                                                                  salesQuotationTable.CurrencyCode);

        this.AVANetPG1Price = salesQuotationTable.CurrencyCode == priceDiscTable.Currency ? priceDiscTable.Amount :
                                                                    salesQuotationTable.AVAExchangeRate != 0 ? (priceDiscTable.Amount *salesQuotationTable.AVAExchangeRate  ) / 100  :
                                                                    CurrencyExchangeHelper::amount(priceDiscTable.Amount,priceDiscTable.Currency);
    }
    if(_netPG2Price)
    {
        priceDiscTable = AVAPriceDiscGroupSearch::findPriceDisc(PriceType::PriceSales,
                                                                  salesQuotationTable.AVANetPG2,
                                                                  '',
                                                                  this.itemId,
                                                                  this.KCS_PriceDate != dateNull() ? this.KCS_PriceDate : DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),
                                                                  salesQuotationTable.CurrencyCode);

        this.AVANetPG2Price = salesQuotationTable.CurrencyCode == priceDiscTable.Currency ? priceDiscTable.Amount :
                                                                    salesQuotationTable.AVAExchangeRate != 0 ? (priceDiscTable.Amount *salesQuotationTable.AVAExchangeRate  ) / 100  :
                                                                    CurrencyExchangeHelper::amount(priceDiscTable.Amount,priceDiscTable.Currency);
    }


    this.AVABestPrice = this.AVALPDiscountedPrice;
    this.AVABestPrice = this.AVANetPG1Price > 0 ? (this.AVABestPrice > 0  ? min( this.AVABestPrice, this.AVANetPG1Price) : this.AVANetPG1Price) :   this.AVABestPrice;
    this.AVABestPrice = this.AVANetPG2Price > 0 ? (this.AVABestPrice > 0  ? min( this.AVABestPrice, this.AVANetPG2Price) : this.AVANetPG2Price) :   this.AVABestPrice;

    if(_calcMasterPrice && this.SalesPrice == 0)
    {
        masterSalesPrice = this.AVAGetMasterSalesPrice();
        this.AVAMasterPrice = masterSalesPrice;
        this.KCS_CalcMark = (masterSalesPrice != 0 && masterSalesPrice <= this.AVABestPrice) ?  #M : '';
        if (masterSalesPrice != 0 && (masterSalesPrice <= this.AVABestPrice || this.AVABestPrice == 0))
        {
            this.SalesPrice   =  masterSalesPrice;
        }
    }

    if (this.SalesPrice == 0 && this.KCS_CalcMark != 'M')
    {
        select  firstonly SalesPrice, RecId, QuotationId from  existedQuotLineItem
            where existedQuotLineItem.QuotationId == this.QuotationId
               && existedQuotLineItem.ItemId      == this.itemId
               && existedQuotLineItem.RecId       != this.RecId;
        if (existedQuotLineItem.RecId)
        {
            this.SalesPrice = existedQuotLineItem.SalesPrice;
        }
        else
        {
            this.SalesPrice = this.AVABestPrice;     
        }
    }
}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>SalesPrice</returns>
public SalesPrice AVAGetMasterSalesPrice()
{
    SalesPrice              masterSalesPrice = 0;
    SalesQuotationTable     salesQuotationTable  = this.salesQuotationTable();
    SalesQuotationTable     refSalesQuotationTable;
    SalesQuotationLine      refSalesQuotationLine;
    InventDim               inventDim = this.inventDim();
    InventDim               refInventDim;

    if (salesQuotationTable.KCS_RefQuotationId != '')
    {
        select firstonly SalesPrice from refSalesQuotationLine
            where refSalesQuotationLine.QuotationId == salesQuotationTable.KCS_RefQuotationId
               && refSalesQuotationLine.ItemId      == this.ItemId
                    join refInventDim
                        where refInventDim.inventDimId   == refSalesQuotationLine.InventDimId
                           && refInventDim.configId      == inventDim.configId
                           && refInventDim.InventColorId == inventDim.InventColorId
                           && refInventDim.InventSizeId  == inventDim.InventSizeId;

        masterSalesPrice = refSalesQuotationLine.SalesPrice;
        if (masterSalesPrice != 0)
        {
            refSalesQuotationTable = salesQuotationTable::find(salesQuotationTable.KCS_RefQuotationId);
            if (salesQuotationTable.CurrencyCode != refSalesQuotationTable.CurrencyCode)
            {
                CurrencyExchangeHelper  currencyExchangeHelper = CurrencyExchangeHelper::newExchangeDate(Ledger::current(),DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
                masterSalesPrice =  currencyExchangeHelper.calculateCurrencyToCurrency(salesQuotationTable.CurrencyCode, refSalesQuotationTable.CurrencyCode,masterSalesPrice,true);

            }
        }
    }

    return masterSalesPrice;
}

