/// <summary>
/// display method showing if documents exist for record
/// </summary>
/// <param name = "_this">SalesQuotationLine</param>
/// <returns>'T' if documents exist and 'o' if not</returns>
[SysClientCacheDataMethodAttribute(true)]
public static display AVAshowDocText showDocText(SalesQuotationLine _this)
{
    #DEFINE.DocExists('T')
    #DEFINE.DocNotExists('o')

    if ((select firstonly docuRef
        where docuRef.RefCompanyId  == _this.DataAreaId
            && docuRef.RefTableId   == _this.TableId
            && docuRef.RefRecId     == _this.RecId).RecId)
    {
        return #DocExists;
    }

    return #DocNotExists;
}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "_span">boolean</param>
void AVAsetQty(boolean _span = false)
{
    SalesQuotationLine      updLine;
    //SalesQuotationTable     sqt;
    DiscPct             discPct;
    Amount              amount;
    PriceUnit           priceUnit;
    Qty                 qty;

    if (!_span)
    {
        if (this.KCS_QLInternalPosition == 1)
        {
            while select forupdate updLine 
                                       where updLine.QuotationId == this.QuotationId
                                          && updLine.KCS_QLLVPosition == this.KCS_QLLVPosition
                                          && updLine.KCS_QLInternalPosition > 1
                                          && updLine.KCS_Span
            {
                updLine.SalesQty        = this.SalesQty / updLine.KCS_Span;
                if ((updLine.ProjTransType == QuotationProjTransType::None) ||
                (updLine.ProjTransType == QuotationProjTransType::Item))
                {
                    updLine.salesPurchLineInterface().resetPriceAgreement();
                    updLine.initSalesQty();
                    updLine.setPriceDisc(updLine.inventDim());
                    updLine.calcPackingUnitQty(updLine.inventDim());
                    InventMovement::bufferSetTransQtyUnit(updLine);
                    updLine.setInventDeliverNow();
                }
                ttsbegin;
                updLine.update();
                ttscommit;
            }
        }
        else if (this.KCS_QLInternalPosition > 1 && this.SalesQty)
        {
            this.KCS_Span   = SalesQuotationLine::AVAfindFirstInternalPosition(this.QuotationId,this.KCS_QLLVPosition).SalesQty / this.SalesQty;
            /*if (this.RecId)
            {
                this.doUpdate();
            }*/
            if ((this.ProjTransType == QuotationProjTransType::None) ||
            (this.ProjTransType == QuotationProjTransType::Item))
            {
                this.salesPurchLineInterface().resetPriceAgreement();
                this.initSalesQty();
                this.setPriceDisc(this.inventDim());
                this.calcPackingUnitQty(this.inventDim());
                InventMovement::bufferSetTransQtyUnit(this);
                this.setInventDeliverNow();
            }
        }
    }
    else
    {
        if (this.KCS_QLInternalPosition > 1 && this.KCS_Span)
        {
            this.SalesQty               = SalesQuotationLine::AVAfindFirstInternalPosition(this.QuotationId,this.KCS_QLLVPosition).SalesQty / this.KCS_Span;
            if ((this.ProjTransType == QuotationProjTransType::None) ||
            (this.ProjTransType == QuotationProjTransType::Item))
            {
                this.salesPurchLineInterface().resetPriceAgreement();
                this.initSalesQty();
                this.setPriceDisc(this.InventDim());
                this.calcPackingUnitQty(this.inventDim());
                InventMovement::bufferSetTransQtyUnit(this);
                this.setInventDeliverNow();
            }
        }
    }

    discPct = this.salesQuotationTable().DiscPercent;
    amount = (select sum(LineAmount) from SalesQuotationLine
                    where SalesQuotationLine.QuotationId == this.QuotationId
                       && SalesQuotationLine.KCS_QLLVPosition  == this.KCS_QLLVPosition
                       && SalesQuotationLine.RecId != this.RecId).LineAmount;
    amount = amount + this.LineAmount;

    if (discPct)
    {
        amount  = amount - amount * discPct / 100;
    }
    updLine.clear();
    updLine     = SalesQuotationLine::AVAfindFirstInternalPosition(this.QuotationId, this.KCS_QLLVPosition);
    qty         = updLine.SalesQty ? updLine.SalesQty : 1;
    priceUnit   = updLine.PriceUnit ? updLine.PriceUnit : 1;

    amount = decRound((amount / qty), 2);
    amount = amount * qty;
    this.KCS_QLLVPrice  = amount / qty * priceUnit;
    this.KCS_QLLVAmount = this.KCS_QLLVPrice * qty / priceUnit;     

    SalesQuotationTable::AVASetQuotNotPosted(this.QuotationId);
}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "_quotationId">QuotationIdBase</param>
/// <param name = "_lVPosition">KCS_QLLVPosition</param>
/// <returns>SalesQuotationLine</returns>
static SalesQuotationLine  AVAfindFirstInternalPosition(QuotationIdBase   _quotationId, KCS_QLLVPosition _lVPosition)
{
    SalesQuotationLine      salesQuotationLine;

    select firstonly salesQuotationLine where salesQuotationLine.QuotationId                == _quotationId      &&
                                              salesQuotationLine.KCS_QLLVPosition           == _lVPosition   &&
                                               salesQuotationLine.KCS_QLInternalPosition    == 1;
    return salesQuotationLine;
}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "_salesQuotationLine">SalesQuotationLine</param>
/// <param name = "_updateCurLine">boolean</param>
void AVASetLVPrices(SalesQuotationLine _salesQuotationLine, boolean _updateCurLine = true)
{
    SalesQuotationLine  updLine;
    Amount              amount;
    PriceUnit           priceUnit;
    Qty                 qty;
    DiscPct             discPct;

    if (_salesQuotationLine.KCS_QLInternalPosition)     // nur wenn Mitglied einer Stützweitengruppe
    {
        discPct = _salesQuotationLine.salesQuotationTable().DiscPercent;

        if (!_salesQuotationLine.KCS_CRMIsAlternativeLine)
        {
            amount = (select sum(LineAmount) from SalesQuotationLine
                    where SalesQuotationLine.QuotationId == _salesQuotationLine.QuotationId
                        && SalesQuotationLine.KCS_QLLVPosition  == _salesQuotationLine.KCS_QLLVPosition
                        && SalesQuotationLine.RecId             != _salesQuotationLine.RecId).LineAmount;

            amount = amount + _salesQuotationLine.LineAmount;
        }
        else
        {
            while select updLine where updLine.QuotationId == _salesQuotationLine.QuotationId
                                && updLine.KCS_QLLVPosition == _salesQuotationLine.KCS_QLLVPosition
            {
                if (updLine.LineAmount)
                {
                    amount += updLine.LineAmount;
                }
                else
                {
                    amount += updLine.SalesPrice * updLine.SalesQty / (updLine.PriceUnit ? updLine.PriceUnit : 1);
                }
            }
        }

        if (discPct)
        {
            amount  = amount - amount * discPct / 100;
        }

        updLine.clear();
        updLine     = SalesQuotationLine::AVAfindFirstInternalPosition(_salesQuotationLine.QuotationId,_salesQuotationLine.KCS_QLLVPosition);
        if (updLine.RecId   == _salesQuotationLine.RecId)
        {
            qty         = _salesQuotationLine.SalesQty ? _salesQuotationLine.SalesQty : 1;
            priceUnit   = _salesQuotationLine.PriceUnit ? _salesQuotationLine.PriceUnit : 1;
        }
        else
        {
            qty         = updLine.SalesQty ? updLine.SalesQty : 1;
            priceUnit   = updLine.PriceUnit ? updLine.PriceUnit : 1;
        }

        //--> KCS/RIPSK/LU_TASK1235001785/25.10.2010
        amount = decRound((amount / qty), 2);
        amount = amount * qty;
        //<-- KCS/RIPSK/LU_TASK1235001785/25.10.2010

        updLine.clear();
        while select forupdate updLine
    where   updLine.QuotationId         == _salesQuotationLine.QuotationId
        &&  updLine.KCS_QLLVPosition    == _salesQuotationLine.KCS_QLLVPosition
        && updLine.RecId != _salesQuotationLine.RecId
        {
            updLine.KCS_QLLVPrice  = amount / qty * priceUnit;
            updLine.KCS_QLLVAmount = updLine.KCS_QLLVPrice * qty / priceUnit;
            ttsbegin;
            updLine.doUpdate();
            ttscommit;
        }
        if (_updateCurLine)
        {
            _salesQuotationLine.KCS_QLLVPrice = amount / qty * priceUnit;
            _salesQuotationLine.KCS_QLLVAmount = amount;
        }
    }
    SalesQuotationTable::AVASetQuotNotPosted(_salesQuotationLine.QuotationId);
}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "_inventTable">InventTable</param>
public void initFromInventTable(InventTable _inventTable)
{
    KCS_PriceDate locKCS_PriceDate;

    next initFromInventTable(_inventTable);

    if (!this.KCS_GAEBOZ)
    {
        this.SalesQty = 0;
    }
    else
    {
        if (!KCS_GAEBPos::existOZ(this.salesQuotationTable().KCS_GAEBImportID, this.KCS_GAEBOZ))
        {
            this.SalesQty = 0;
        }
    }

    locKCS_PriceDate = this.AVAPriceDate();

    this.AVAPriceSurchargeCode = _inventTable.avaGetPriceSurchargeCode();

    if(this.AVAPriceSurchargeCode)
    {
        if(this.KCS_PriceDate == dateNull())
        {
            this.AVAPriceSurchargePercentage    = _inventTable.avaGetPriceSurchargePercentage(this.AVAPriceSurchargeCode);
        }
        else
        {
            this.avaSetSurchargeValues();
        }
    }
}

 /// <summary>
 ///     AVA <c>avaSetSurchargeValues</c> method.
 /// </summary>
public void avaSetSurchargeValues()
 {
     if(this.AVAPriceSurchargeCode)
     {
         if(this.KCS_PriceDate == dateNull())
         {
             this.AVAPriceSurchargePercentage    = AVAPriceSurchargeValues::find(this.AVAPriceSurchargeCode).Percentage;
         }
         else
         {
             this.AVAPriceSurchargePercentage    = AVAPriceSurchargeValues::findAtDate(this.AVAPriceSurchargeCode, this.KCS_PriceDate).Percentage;
         }
     }
 }

