/// <summary>
/// KCS_getHK2SalesUnit from AX2009
/// </summary>
/// <returns>KCS_HK2</returns>
display KCS_HK2 AVAgetHK2SalesUnit()
{
    /*PriceUnit   priceUnit = UnitConvert::qty((this.PriceUnit ? this.PriceUnit : 1),
                                           this.SalesUnit, this.inventTable().inventUnitId(), this.ItemId);*/
    PriceUnit                       priceUnit;
    InventTable                     locInventTable = this.inventTable();
    TransDate                       transDate = this.KCS_PriceDate != dateNull() ? this.KCS_PriceDate : DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());        
    if(locInventTable.inventItemSetupSupplyType().DefaultOrderType == ReqPOType::Production) 
    {
        return locInventTable.inventTableModuleSales().NDX_showHK2current(transDate) * this.PriceUnit / 1000;
    }
    else
    {
        if(locInventTable.inventUnitId() != this.SalesUnit)
        {
            UnitOfMeasureConverter_Product  unitConverter;
            unitConverter = UnitOfMeasureConverter_Product::construct();
            unitConverter.parmProduct(InventTable::find(this.ItemId).Product);
            unitConverter.parmFromUnitOfMeasure(UnitOfMeasure::unitOfMeasureIdBySymbol(this.SalesUnit));
            unitConverter.parmToUnitOfMeasure(UnitOfMeasure::unitOfMeasureIdBySymbol(locInventTable.inventUnitId()));
            unitConverter.parmRoundAbsoluteValue(NoYes::Yes);
            unitConverter.parmApplyRounding(NoYes::Yes);
            priceUnit = unitConverter.convertValue(this.PriceUnit ? this.PriceUnit : 1);
        }
        else
        {
            priceUnit = this.PriceUnit ? this.PriceUnit : 1;
        }

        //return this.AVAgetHK2perQty(priceUnit) * priceUnit;
        if(AVASalesParameters::find().HKFromSupportTable)
        {
            return this.AVAgetNDGHK2perQty();
        }
        else
        {
            return this.AVAgetHK2perQty(priceUnit); // priceUnit already gets multiplied in deeper function InventTable.KCS_GetHV1perQty(...)
        }
    }
}

/// <summary>
/// KCS_getHK2perQty from AX2009
/// </summary>
/// <param name = "_qty">Qta</param>
/// <returns>KCS_HK2</returns>
display KCS_HK2 AVAgetHK2perQty(Qty _qty=1)
{
    InventTable     locinventTable = this.inventTable();
    InventTableModule inventTablePurch =  locinventTable.inventTableModulePurch();
    AmountMST         hk2PerPriceUnit; 
    //return this.inventTable().AVAGetHK2perQty(_qty, this.InventDimId, this.AVAPriceDate(), true, true);
    //Qty    purchUnitQty = UnitOfMeasureConverter::convert(1000,UnitOfMeasure::findBySymbol(this.SalesUnit).RecId,UnitOfMeasure::findBySymbol(inventTablePurch.UnitId).RecId,NoYes::No,locinventTable.Product);
    Qty    purchUnitQty = UnitOfMeasureConverter::convert(inventTablePurch.PriceUnit,UnitOfMeasure::findBySymbol(inventTablePurch.UnitId).RecId,UnitOfMeasure::findBySymbol(this.SalesUnit).RecId,NoYes::No,locinventTable.Product);
    hk2PerPriceUnit =    locinventTable.AVAGetHK2perQty(1, this.InventDimId, this.AVAPriceDate(), true, true);
    //return locinventTable.AVAGetHK2perQty((purchUnitQty * _qty)/1000, this.InventDimId, this.AVAPriceDate(), true, true) / inventTablePurch.PriceUnit;
    return _qty *   hk2PerPriceUnit / purchUnitQty  ;
}

/// <summary>
/// display method that calculates HK2 based on the table AVAHK2NDG
/// </summary>
/// <returns>KCS_HK2</returns>
display KCS_HK2 AVAgetNDGHK2perQty()
{
    AVAHK2p1000 avaHK2per1000 = AVAHK2NDG::getHK2p1000(this.ItemId);

    return avaHK2per1000 / 1000;
}

/// <summary>
/// KCS_PriceDate from AX2009
/// </summary>
/// <returns>KCS_PriceDate</returns>
KCS_PriceDate AVAPriceDate()
{
    if (this.KCS_PriceDate)
    {
        return this.KCS_PriceDate;
    }

    if (this.salesQuotationTable().KCS_PriceDate)
    {
        return this.salesQuotationTable().KCS_PriceDate;
    }

    return DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
}

/// <summary>
/// designed by AVANADE calc AVAHKQuotCurrency
/// </summary>
/// <returns>AVAHKQuotCurrency</returns>
AVAHKQuotCurrency   AVAcalcHKQuotCurrency()
{
    AVAHKQuotCurrency ret;

    if (this.KCS_NotCalculated)
    {   
        ret = this.KCS_SonderHK;
    }
    else
    {
        ret = this.KCS_HK2;
    }

    //ret = CurrencyExchangeHelper::amountCur2MST(ret, this.CurrencyCode); 

    if (this.salesQuotationTable().KCS_LimitPriceExchRate > 0)
    {
        ret = ret * this.salesQuotationTable().KCS_LimitPriceExchRate / 100;
    }

    return ret;
}

/// <summary>
/// designed by AVANADE copied from SalesQuotationTable.KCS_getFactor and modified
/// </summary>
/// <param name = "groupName">KCS_GroupNameBase</param>
/// <param name = "itemId">ItemId</param>
/// <returns>KCS_LimitFactorUnitFactor</returns>
KCS_LimitFactorUnitFactor AVAgetLimitFactor(KCS_GroupNameBase groupName, ItemId itemId)
{
    InventTable         inventTable;
    KCS_LimitFactors    kcs_LimitFactors;

    // Artikelsuche
    select firstonly UnitFactor from kcs_LimitFactors where kcs_LimitFactors.ItemRelation == itemId &&
                                                        kcs_LimitFactors.GroupName == groupName &&
                                                        kcs_LimitFactors.ItemCode == 0;
    if (kcs_LimitFactors.UnitFactor)
    {
        return kcs_LimitFactors.UnitFactor;
    }

    // Gruppensuche
    select firstonly KCS_GoodsID from inventTable where inventTable.ItemId == itemId;
    select firstonly UnitFactor from kcs_LimitFactors where kcs_LimitFactors.ItemRelation == inventTable.KCS_GoodsID &&
                                                        kcs_LimitFactors.GroupName == groupName &&
                                                        kcs_LimitFactors.ItemCode == 1;
    if (kcs_LimitFactors.UnitFactor)
    {
        return kcs_LimitFactors.UnitFactor;
    }

    // Globalfaktor
    select firstonly UnitFactor from kcs_LimitFactors where kcs_LimitFactors.GroupName == groupName &&
                                                        kcs_LimitFactors.ItemCode == 2;

    return kcs_LimitFactors.UnitFactor;
}

/// <summary>
/// designed by AVANADE calc AVALimitUnitFactor
/// </summary>
/// <returns>KCS_LimitFactorUnitFactor</returns>
KCS_LimitFactorUnitFactor AVAcalcLimitUnitFactor()
{
    KCS_LimitFactorUnitFactor   ret;
    SalesQuotationTable         salesQuotationTable;

    salesQuotationTable = this.salesQuotationTable();
    ret = this.AVAgetLimitFactor(salesQuotationTable.KCS_LimitGroupName, this.ItemId);
    return ret;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_specialDiscQuotation">_specialDiscQuotation</param>
/// <returns>_specialDiscQuotation</returns>
KCS_LimitPrice AVAcalcLimitPrice(AVASpecialDiscQuotation        _specialDiscQuotation = null)
{
    KCS_LimitPrice              ret;
    AVASpecialDiscQuotation     specialDiscQuotation;
    real                        factorSD1, factorSD2, factorSD3, factorMaxBonus;
    SalesQuotationTable         salesQuotationTable = this.salesQuotationTable();

    if (_specialDiscQuotation != null)
    {
        specialDiscQuotation = _specialDiscQuotation;    
    }
    else
    {
        specialDiscQuotation = AVASpecialDiscQuotation::find(this.QuotationId);
    }

    if (specialDiscQuotation)
    {
        factorSD1 = specialDiscQuotation.SpecialDiscountPct1 ? (1-(specialDiscQuotation.SpecialDiscountPct1/100)) : 1;
        factorSD2 = specialDiscQuotation.SpecialDiscountPct2 ? (1-(specialDiscQuotation.SpecialDiscountPct2/100)) : 1;
        factorSD3 = specialDiscQuotation.SpecialDiscountPct3 ? (1-(specialDiscQuotation.SpecialDiscountPct3/100)) : 1;
    }
    factorMaxBonus = salesQuotationTable.KCS_MaxBonusAmount ? (1-(salesQuotationTable.KCS_MaxBonusAmount/100)) : 1;

    if (!this.AVAHKQuotCurrency)
    {
        this.AVAHKQuotCurrency = this.AVAcalcHKQuotCurrency();
    }
    if (!this.KCS_LimitUnitFactor)
    {
        this.KCS_LimitUnitFactor      = this.AVAcalcLimitUnitFactor();
    }
    ret = this.AVAHKQuotCurrency * this.KCS_LimitUnitFactor / factorSD1 / factorSD2 / factorSD3 / factorMaxBonus;

    //ret = CurrencyExchangeHelper::amount(ret, this.CurrencyCode);

    return ret;
}

/// <summary>
/// designed by AVANADE calc KCS_LimitPricePuffer
/// </summary>
/// <returns>KCS_LimitPricePuffer</returns>
KCS_LimitPricePuffer AVAcalcLimitPricePuffer()
{
    KCS_LimitPricePuffer    ret;
    SalesPrice              salesPrice;


    if (!this.KCS_LimitPrice || !this.SalesPrice)
    {
        return -999.99;
    }

    if (this.KCS_CalcSalesPrice)
    {
        salesPrice = this.AVAcalcDiscPercent() ? this.KCS_CalcSalesPrice - (this.AVAcalcDiscPercent() * (this.KCS_CalcSalesPrice / 100)) : this.KCS_CalcSalesPrice;
        ret = salesPrice - this.KCS_LimitPrice;
        ret = salesPrice ? (ret * 100) / salesPrice : 0;

    }
    else
    {
        salesPrice = this.discPercent() ? this.SalesPrice - (this.discPercent() * (this.SalesPrice / 100)) : this.SalesPrice;
        ret = salesPrice - this.KCS_LimitPrice;
        ret = salesPrice ? (ret * 100) / salesPrice : 0;
    }

    return ret;
}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "_salesQuotationLine">SalesQuotationLine</param>
/// <returns>AVAHKQuotFactor</returns>
public static display AVAHKQuotFactor AVAHKQuotFactor(SalesQuotationLine _salesQuotationLine)
{
    AVAHKQuotFactor              ret;
    AVASpecialDiscQuotation     specialDiscQuotation;
    real                        factorSD1, factorSD2, factorSD3, factorMaxBonus;
    SalesQuotationTable         salesQuotationTable = _salesQuotationLine.salesQuotationTable();

    specialDiscQuotation = AVASpecialDiscQuotation::find(_salesQuotationLine.QuotationId);

    if (specialDiscQuotation)
    {
        factorSD1 = specialDiscQuotation.SpecialDiscountPct1 ? (1-(specialDiscQuotation.SpecialDiscountPct1/100)) : 1;
        factorSD2 = specialDiscQuotation.SpecialDiscountPct2 ? (1-(specialDiscQuotation.SpecialDiscountPct2/100)) : 1;
        factorSD3 = specialDiscQuotation.SpecialDiscountPct3 ? (1-(specialDiscQuotation.SpecialDiscountPct3/100)) : 1;
    }
    factorMaxBonus = salesQuotationTable.KCS_MaxBonusAmount ? (1-salesQuotationTable.KCS_MaxBonusAmount/100) : 1;

    ret = (_salesQuotationLine.SalesPrice * factorSD1 * factorSD2 * factorSD3 * factorMaxBonus) / (_salesQuotationLine.AVAHKQuotCurrency ? _salesQuotationLine.AVAHKQuotCurrency : 1);

    return ret;


}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "_salesQuotationLine">SalesQuotationLine</param>/// 
/// <returns>AVALPFactor</returns>
public static display AVALPFactor AVALPFactor(SalesQuotationLine _salesQuotationLine)
{
    AVALPFactor ret;

    ret = _salesQuotationLine.SalesPrice / (_salesQuotationLine.KCS_LPSalesPrice ? _salesQuotationLine.KCS_LPSalesPrice : 1);

    return ret;
}

/// <summary>
/// designed by AVANADE from AX2009 KCS_ExistMultipleItem
/// </summary>
/// <param name = "_salesQuotationLine">SalesQuotationLine</param> 
/// <returns>boolean</returns> 
public static boolean existMultipleItem(SalesQuotationLine _salesQuotationLine)
{
    SalesQuotationLine  salesQuotationLine;
    InventTable         inventTable     = _salesQuotationLine.inventTable();
    InventDim           inventDim       = _salesQuotationLine.inventDim();
    InventDim           inventDimLocal;


    select firstonly salesQuotationLine
            index   QuotationItemIdx
            where   salesQuotationLine.QuotationId      == _salesQuotationLine.QuotationId
            &&      salesQuotationLine.ItemId           == _salesQuotationLine.ItemId
            &&      salesQuotationLine.RecId            != _salesQuotationLine.RecId
            #AVAInventDimJoinPrice(salesQuotationLine.InventDimId, inventDimLocal, inventDim, inventTable);

    return salesQuotationLine.RecId != 0;
}

/// <summary>
/// Returns the number of quotation lines with the same itemId
/// </summary>
/// <param name = "_quotationId">QuotationId</param>
/// <param name = "_itemId">ItemId</param>
/// <returns>int</returns>
public static int64 avaCountSimilarItems(QuotationId _quotationId, ItemId _itemId)
{
    SalesQuotationLine  salesQuotationLine;

    select count(RecId) from salesQuotationLine
            index   QuotationItemIdx
            where   salesQuotationLine.QuotationId      == _quotationId
            &&      salesQuotationLine.ItemId           == _itemId;

    return salesQuotationLine.RecId;
}

/// <summary>
/// designed by AVANADE from AX2009 KCS_updateCalcFieldsQuotationLine
/// </summary>
/// <param name = "_salesQuotationLine">SalesQuotationLine</param>
/// <param name = "_calcMark">KCS_CalcMark</param>
void AVAupdateCalcFieldsQuotationLine(SalesQuotationLine _salesQuotationLine = this, KCS_CalcMark _calcMark = '')
{
    SalesQuotationLine  localSalesQuotationLine;
    amount              prevAmount;
    InventTable         localInventTable = _salesQuotationLine.inventTable();   
    InventDim           inventDimLocal, inventDim;  
    //SalesQuotationTable sqt;

    inventDim = _salesQuotationLine.inventDim();                                

    while select forupdate localSalesQuotationLine
                    index   QuotationItemIdx                                                
    where   localSalesQuotationLine.QuotationId      == _salesQuotationLine.QuotationId
                &&      localSalesQuotationLine.ItemId           == _salesQuotationLine.ItemId
                &&      localSalesQuotationLine.RecId            != _salesQuotationLine.RecId
                #AVAInventDimJoinPrice(localSalesQuotationLine.InventDimId, inventDimLocal, inventDim, localInventTable)          
    {
        ttsbegin;
        prevAmount                                         = localSalesQuotationLine.LineAmount;
        localSalesQuotationLine.KCS_CalcLinePercent        = _salesQuotationLine.KCS_CalcLinePercent;
        localSalesQuotationLine.KCS_CalcMultiLnPercent     = _salesQuotationLine.KCS_CalcMultiLnPercent;
        localSalesQuotationLine.KCS_CalcSalesPrice         = _salesQuotationLine.KCS_CalcSalesPrice;
        localSalesQuotationLine.KCS_CalcUseEndDisc         = _salesQuotationLine.KCS_CalcUseEndDisc;
        localSalesQuotationLine.KCS_CalcUseLineDisc        = _salesQuotationLine.KCS_CalcUseLineDisc;
        localSalesQuotationLine.KCS_CalcUseMultilineDisc   = _salesQuotationLine.KCS_CalcUseMultilineDisc;
        localSalesQuotationLine.SalesPrice                 = _salesQuotationLine.SalesPrice;
        localSalesQuotationLine.LineAmount                 = localSalesQuotationLine.calcLineAmountForced();
        localSalesQuotationLine.KCS_calcMark               = _calcMark;
        localSalesQuotationLine.KCS_MultipleItem           = 'X'; 
        localSalesQuotationLine.KCS_LimitPrice             = localSalesQuotationLine.AVAcalcLimitPrice();
        localSalesQuotationLine.KCS_LimitPricePuffer       = localSalesQuotationLine.AVAcalcLimitPricePuffer();
        localSalesQuotationLine.AVASetCalcPDPPrice();

        if (_salesQuotationLine.KCS_NotCalculated)
        {
            localSalesQuotationLine = this.AVAcopyNotCalcLines(_salesQuotationLine, localSalesQuotationLine);
        }

        localSalesQuotationLine.doUpdate();

        ttscommit;
    }
    /*ttsbegin;
    sqt = _salesQuotationLine.salesQuotationTable(true);
    sqt.AVAPosted = NoYes::No;
    sqt.AVAPostedEnum = AVAPostedEnum::NotPosted;
    sqt.doUpdate();
    ttscommit;*/
    SalesQuotationTable::AVASetQuotNotPosted(_salesQuotationLine.QuotationId);

    /*if (FormDataUtil::isFormDataSource(this))
    {
        FormDataUtil::getFormDataSource(this).research(true);
    }*/

}

/// <summary>
/// designed by AVANADE from AX2009 KCS_copyNotCalcLines
/// </summary>
/// <param name = "_fromSQL">SalesQuotationLine</param>
/// <param name = "_toSQL">SalesQuotationLine</param>
/// <returns>SalesQuotationLine</returns>
SalesQuotationLine AVAcopyNotCalcLines(SalesQuotationLine _fromSQL, SalesQuotationLine _toSQL = this)
{
    _toSQL.KCS_SonderHK         = _fromSQL.KCS_SonderHK;
    _toSQL.KCS_ModelNumber      = _fromSQL.KCS_ModelNumber;
    _toSQL.Name                 = _fromSQL.Name;
    _toSQL.NDXProductName1      = _fromSQL.NDXProductName1;
    _toSQL.NDXProductName2      = _fromSQL.NDXProductName2;

    _toSQL.KCS_LimitPrice             = _toSQL.AVAcalcLimitPrice();
    _toSQL.KCS_LimitPricePuffer       = _toSQL.AVAcalcLimitPricePuffer();

    return _toSQL;
}

/// <summary>
/// designed by AVANADE from AX2009 KCS_calcDiscPercent
/// </summary>
/// <returns>DiscPct</returns>
DiscPct AVAcalcDiscPercent()
{
    if (!this.KCS_CalcUseLineDisc)
    {
        this.KCS_CalcLinePercent = 0;
    }

    if (!this.KCS_CalcUseMultilineDisc)
    {
        this.KCS_CalcMultiLnPercent = 0;
    }

    return PriceDisc::discPercent(SalesParameters::find().Disc, this.KCS_calcLinePercent, this.KCS_calcMultiLnPercent);
}

/// <summary>
/// designed by AVANADE from AX2009 KCS_SetCalcPDPPrice
/// </summary>
void AVASetCalcPDPPrice()
{
    // Berechnen/Aktualisieren VRP KCS_CalcPDPrice
    Percent p = this.AVAcalcDiscPercent()/100;

    this.KCS_CalcPDPPrice = this.KCS_CalcSalesPrice * (1 - p);

}

