/// <summary>
/// designed from AVA
/// </summary>
public void AVAUpdateGAEBOZ()
{
    SalesQuotationLine  sql;
    Qty                 GAEBQty;

    if (this.KCS_QLInternalPosition && this.KCS_GAEBOZ)
    {
        GAEBQty = KCS_GAEBPos::find(this.SalesQuotationTable().KCS_GAEBImportID, this.KCS_GAEBOZ).ArtQty;

        while select forupdate sql where sql.QuotationId == this.QuotationId
                                      && sql.KCS_QLLVPosition == this.KCS_QLLVPosition
                                      && sql.RecId != this.RecId
        {
            ttsbegin;
            sql.KCS_GAEBOZ = this.KCS_GAEBOZ;
            if (!sql.SalesQty)
            {
                sql.SalesQty = GAEBQty;
                sql.salesQtyModified();
                sql.AVAsetQty();
            }
            sql.doUpdate();
            ttscommit;
        }
    }
    else if (this.KCS_QLInternalPosition && !this.KCS_GAEBOZ)
    {
        while select forupdate sql where sql.QuotationId == this.QuotationId
                                      && sql.KCS_QLLVPosition == this.KCS_QLLVPosition
                                      && sql.RecId != this.RecId
        {
            ttsbegin;
            sql.KCS_GAEBOZ = this.KCS_GAEBOZ;
            sql.doUpdate();
            ttscommit;
        }

    }
}

/// <summary>
/// designed from AVA
/// </summary>
public void AVAsetAlternativeLine()
{
    SalesQuotationLine  sql;

    if (this.KCS_QLLVPosition && this.KCS_QLInternalPosition)
    {
        while select forupdate sql where sql.QuotationId == this.QuotationId
                                      && sql.KCS_QLLVPosition == this.KCS_QLLVPosition
                                      && sql.RecId != this.RecId
        {
            ttsbegin;
            sql.KCS_CRMIsAlternativeLine = this.KCS_CRMIsAlternativeLine;
            if (sql.KCS_CRMIsAlternativeLine)
            {
                sql.LineAmount = 0;
            }
            else
            {
                sql.LineAmount = sql.calcLineAmountForced();
            }
            //sql.doUpdate();
            sql.update();
            ttscommit;
        }
        this.modifiedField(fieldNum(SalesQuotationLine, KCS_Span));
    }
}

