void  insert(   boolean     _dropInvent,
                boolean     _findMarkup,
                Common      _childBuffer,
                boolean     _skipsalesQuotationTableUpdate)
{
    if(SalesQuotationLine::avaCountSimilarItems(this.QuotationId, this.ItemId) >= 1)
    {
        //this.avaAddDuplicateMark();
        this.KCS_MultipleItem = 'X';
    }

    //if (!AVASalesParameters::find().SalesQuotImportModus)
    if (!SysUserInfo::find(curUserId()).AVADataImportUser)
    {
        this.avaUpdateHK2();
    }
    else
    {
        this.AVAHKQuotCurrency = this.AVAcalcHKQuotCurrency();
    }

    next insert(_dropInvent, _findMarkup, _childBuffer, _skipsalesQuotationTableUpdate);
}

/// <summary>
/// Adds duplicate marks to lines with duplicate itemIds
/// </summary>
public void avaAddDuplicateMark()
{
    SalesQuotationLine avaSalesQuotationLineLoc;

    ttsbegin;

    update_recordset avaSalesQuotationLineLoc
        setting KCS_MultipleItem = 'X'
        where avaSalesQuotationLineLoc.ItemId == this.itemId
        //&& avaSalesQuotationLineLoc.QuotationId == this.quotationId;
        && avasalesquotationlineloc.QuotationId == this.QuotationId
        && avasalesquotationlineloc.RecId != this.RecId;

    ttscommit;
}

/// <summary>
/// Removes duplicate marks from lines with unique itemIds
/// </summary>
/// <param name = "_quotationId">QuotationId</param>
/// <param name = "_itemId">ItemId</param>
public static void avaRemoveDuplicateMark(QuotationId _quotationId, ItemId _itemId)
{
    SalesQuotationLine avaSalesQuotationLineLoc;

    ttsbegin;

    update_recordset avaSalesQuotationLineLoc
        setting KCS_MultipleItem = ''
        where avaSalesQuotationLineLoc.ItemId == _itemId
        && avaSalesQuotationLineLoc.QuotationId == _quotationId;

    ttscommit;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>KCS_QLLVPosition</returns>
public KCS_QLLVPosition getLastQLLPosition()
{

    SalesQuotationLine      lastSalesQuotationLine;

    select firstonly KCS_QLLVPosition from lastSalesQuotationLine
        order by KCS_QLLVPosition DESC
        where lastSalesQuotationLine.QuotationId == this.QuotationId;

    return lastSalesQuotationLine.KCS_QLLVPosition;
}

/// <summary>
/// AVA_010889_SQBuildLineNumFromLVPos
/// </summary>
/// <returns>LineNum</returns>
public LineNum buildLineNumFromLVPos()
{
    LineNum                 ret;
    KCS_QLLVPosition        lv = this.KCS_QLLVPosition;
    KCS_QLInternalPosition  internalPos = this.KCS_QLInternalPosition;
    int64                   lvInt;

    internalPos = internalPos / 100;
    //lv = subStr(strKeep(lv, '0123456789'), 1, 14);
    //ret = str2Num(lv) + internalPos;
    lv = strKeep(lv, '0123456789');
    while (subStr(lv,1,1) == '0')
    {
        lv = subStr(lv, 2, strLen(lv));
    }
    lv = subStr(lv, 1, 18);

    lvInt = str2Int64(lv);
    if (lvInt > realMax())
    {
        lv = int642Str(lvInt);
        lv = subStr(lv, 1, 15);
        lvInt = str2Int64(lv);
    }
    ret = lvInt + internalPos;
    return ret;
}

/// <summary>
/// AVA/WEN/2025/05/06    AVA_013252_AltItemsWithSpan
/// </summary>
/// <param name = "_quotationId">QuotationIdBase</param>
/// <param name = "_lVPosition">KCS_QLLVPosition</param>
/// <returns>KCS_QLInternalPosition</returns>
static KCS_QLInternalPosition  AVAMaxInternalPosition(QuotationIdBase   _quotationId, KCS_QLLVPosition _lVPosition)
{
    SalesQuotationLine      salesQuotationLine;

    select maxof(KCS_QLInternalPosition) from salesQuotationLine where salesQuotationLine.QuotationId                == _quotationId      &&
                                              salesQuotationLine.KCS_QLLVPosition           == _lVPosition;
    return salesQuotationLine.KCS_QLInternalPosition;
}

